<?php $statuses=['available'=>'Có sẵn','damaged'=>'Hỏng','lost'=>'Mất','retired'=>'Ngừng sử dụng','on_loan'=>'Đang mượn','reserved'=>'Giữ chỗ']; $conditions=['good'=>'Tốt','worn'=>'Cũ','damaged'=>'Hỏng','lost'=>'Mất']; ?>
<div class="page-title-row"><div><span class="eyebrow">KHO SÁCH</span><h1>Bản sao sách</h1><p><?= e($book['title']) ?> · <?= e($book['book_code']) ?> · <?= (int)$book['available_copies'] ?> bản có sẵn</p></div><a class="button button-outline" href="<?= e(url('/admin/books')) ?>">Danh mục sách</a></div>
<section class="panel"><h2>Thêm bản sao</h2><form class="form-stack" method="post" action="<?= e(url('/admin/books/'.$book['id'].'/copies')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="0"><div class="form-grid"><label>Mã bản sao<input name="copy_code" maxlength="60" required placeholder="<?= e($book['book_code']) ?>-NEW"></label><label>Mã vạch<input name="barcode" maxlength="80"></label><label>Vị trí kệ<input name="shelf_location" maxlength="120"></label><label>Tình trạng<select name="item_condition"><?php foreach($conditions as $key=>$label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label><label>Trạng thái<select name="status"><?php foreach(array_slice($statuses,0,4) as $key=>$label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label></div><button class="button button-primary">Thêm bản sao</button></form></section>
<section class="panel"><h2>Danh sách bản sao vật lý</h2><div class="table-scroll"><table><thead><tr><th>Mã bản sao / vị trí</th><th>Tình trạng</th><th>Lịch sử</th><th>Cập nhật</th></tr></thead><tbody>
<?php foreach($copies as $copy): ?><tr><td><strong><?= e($copy['copy_code']) ?></strong><small><?= e($copy['shelf_location'] ?: 'Chưa xếp kệ') ?></small><small><?= e($copy['barcode'] ?: '') ?></small></td><td><?= e($statuses[$copy['status']]) ?><small><?= e($conditions[$copy['item_condition']]) ?></small></td><td><?= (int)$copy['history_count'] ?> lượt mượn</td><td>
<?php if(in_array($copy['status'],['on_loan','reserved'],true)): ?><span>Quản lý tại Mượn / Trả</span><?php else: ?>
<details><summary>Sửa bản sao</summary><form class="form-stack" method="post" action="<?= e(url('/admin/books/'.$book['id'].'/copies')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$copy['id'] ?>"><div class="copy-edit-grid"><label>Mã bản sao<input name="copy_code" maxlength="60" value="<?= e($copy['copy_code']) ?>" required></label><label>Mã vạch<input name="barcode" maxlength="80" value="<?= e($copy['barcode']) ?>"></label><label>Vị trí kệ<input name="shelf_location" maxlength="120" value="<?= e($copy['shelf_location']) ?>"></label><label>Tình trạng<select name="item_condition"><?php foreach($conditions as $key=>$label): ?><option value="<?= e($key) ?>"<?= selected($copy['item_condition'],$key) ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Trạng thái<select name="status"><?php foreach(array_slice($statuses,0,4) as $key=>$label): ?><option value="<?= e($key) ?>"<?= selected($copy['status'],$key) ?>><?= e($label) ?></option><?php endforeach; ?></select></label></div><button class="button button-outline">Lưu bản sao</button></form></details>
<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
